import{_ as t,o as e,c as a,a2 as r}from"./chunks/framework.Boholvbs.js";const m=JSON.parse('{"title":"Why json-tool?","description":"","frontmatter":{},"headers":[],"relativePath":"about/why.md","filePath":"about/why.md","lastUpdated":1791661258000}'),s={name:"about/why.md"};function n(i,o,l,d,h,c){return e(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="why-json-tool" tabindex="-1">Why json-tool? <a class="header-anchor" href="#why-json-tool" aria-label="Permalink to &quot;Why json-tool?&quot;">​</a></h1><p>Are you tired of accessing <strong>free websites just to format your JSON content</strong>? Me too. Besides the data protection issue, sometimes we just want to have it formatted and move on.</p><p>json-tool is a simple tool that <strong>does not track you, does not store your data and does not sell your data</strong>. It helps you format, validate and beautify your JSON strings — nothing more, nothing less.</p><p>According to <a href="https://www.thoughtworks.com/content/dam/thoughtworks/documents/radar/2022/10/tr_technology_radar_vol_27_en.pdf" target="_blank" rel="noreferrer">ThoughtWorks in the tech radar 27 (item 76 under <strong>Tools</strong>)</a>, developers should hold the practice of formatting or sharing information in formatting tools that comply with data jurisdiction. json-tool is built with that in mind: all the processing happens locally, in your browser. Nothing is uploaded to a server.</p><h2 id="five-years-of-open-source" tabindex="-1">Five years of open source <a class="header-anchor" href="#five-years-of-open-source" aria-label="Permalink to &quot;Five years of open source&quot;">​</a></h2><p>Five years ago, the project started out of necessity: a JSON formatting tool that could be trusted with sensitive data — one that would not send information to third-party servers filled with ads and tracking scripts. What began as a personal weekend project has quietly grown into something used by thousands of active users.</p><p>Read more:</p><ul><li><a href="https://marabesi.com/web/productivity/utilities/2021/10/24/json-tool-a-companion-for-formatting-json-strings.html?utm_source=json-tool&amp;utm_medium=direct&amp;utm_campaign=jsontool&amp;utm_id=json-tool-docs" target="_blank" rel="noreferrer">Announcing the JSON tool — A companion for formatting json content, focused in privacy</a></li><li><a href="https://marabesi.com/thoughts/five-years-json-tool-3000-active-users.html?utm_source=json-tool&amp;utm_medium=direct&amp;utm_campaign=jsontool&amp;utm_id=json-tool-docs" target="_blank" rel="noreferrer">Five Years of Open Source json-tool and 3,000 Active Users Later</a></li></ul>',8)])])}const p=t(s,[["render",n]]);export{m as __pageData,p as default};
